@FunctionalInterface
public interface OrderValidator {
    boolean isValid(Order order);

    // Default methods are allowed
    default OrderValidator and(OrderValidator other) {
        return order -> this.isValid(order) && other.isValid(order);
    }
}

record Order(Long id, double amount, String status) {}

public class OrderService {
    public List<Order> filterOrders(List<Order> orders, OrderValidator validator) {
        return orders.stream()
            .filter(validator::isValid)  // lambda target
            .toList();
    }

    public static void main(String[] args) {
        var service = new OrderService();
        var orders = List.of(new Order(1L, 100.0, "PENDING"));

        // Lambda expression implements the single abstract method
        var valid = service.filterOrders(orders, order -> order.amount() > 50);
    }
}

