import java.util.function.*;

public class CoreFunctionalInterfaces {
    public static void main(String[] args) {
        Predicate<Integer> isEven = n -> n % 2 == 0;    // T -> boolean
        Function<Integer, Integer> square = n -> n * n; // T -> R
        Consumer<String> printer = System.out::println; // T -> void
        Supplier<String> greeting = () -> "hello";      // () -> T

        System.out.println(isEven.test(4));   // true
        System.out.println(square.apply(5));  // 25
        printer.accept(greeting.get());       // hello
    }
}
