@FunctionalInterface
interface OrderProcessor {
    void processOrder(Order order);

    // Adding this would cause compile error with @FunctionalInterface
    // void cancelOrder(Order order);

    // Default methods are allowed - don't count as abstract
    default void logProcessing(Order order) {
        System.out.println("Processing: " + order.id());
    }
}

record Order(Long id, double amount) {}

public class PaymentService {
    public void executePayment(double amount, PaymentProcessor processor) {
        processor.processPayment(amount);  // Lambda works here
    }

    public static void main(String[] args) {
        var service = new PaymentService();
        // Both work with lambdas
        service.executePayment(100.0, amt -> System.out.println("Paid: " + amt));
    }
}

record Order(Long id, double amount, String status, String customerType) {}

public class OrderFilter {
    // Define reusable predicates
    private static final Predicate<Order> isHighValue = 
        order -> order.amount() > 1000;

    private static final Predicate<Order> isPending = 
        order -> "PENDING".equals(order.status());

    private static final Predicate<Order> isPremiumCustomer = 
        order -> "PREMIUM".equals(order.customerType());

    public List<Order> filterOrders(List<Order> orders) {
        // Compose predicates for complex logic
        var urgentOrders = isHighValue.and(isPending);
        var priorityOrders = urgentOrders.or(isPremiumCustomer);
        var nonPriorityOrders = priorityOrders.negate();

        return orders.stream()
            .filter(priorityOrders)  // Readable, reusable
            .toList();
    }

    public static void main(String[] args) {
        var filter = new OrderFilter();
        var orders = List.of(
            new Order(1L, 1500.0, "PENDING", "REGULAR"),
            new Order(2L, 500.0, "COMPLETE", "PREMIUM")
        );
        var results = filter.filterOrders(orders);
    }
}

