@FunctionalInterface
public interface DataValidator<T> {
    // Single abstract method that can throw checked exception
    ValidationResult validate(T data) throws ValidationException;

    // Default method for composition
    default DataValidator<T> and(DataValidator<T> other) {
        return data -> {
            var firstResult = this.validate(data);
            if (!firstResult.isValid()) return firstResult;
            return other.validate(data);
        };
    }
}

record ValidationResult(boolean isValid, String message) {}
class ValidationException extends Exception {
    public ValidationException(String message) { super(message); }
}

record UserRegistration(String email, String password, int age) {}

public class RegistrationService {
    private final DataValidator<UserRegistration> emailValidator = 
        reg -> reg.email().contains("@") 
            ? new ValidationResult(true, "Valid") 
            : new ValidationResult(false, "Invalid email");

    private final DataValidator<UserRegistration> ageValidator = 
        reg -> reg.age() >= 18 
            ? new ValidationResult(true, "Valid") 
            : new ValidationResult(false, "Must be 18+");

    public void register(UserRegistration reg) throws ValidationException {
        var combinedValidator = emailValidator.and(ageValidator);
        var result = combinedValidator.validate(reg);
        if (!result.isValid()) throw new ValidationException(result.message());
    }
}
